import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:qros_mobile_studio/core/local_vault.dart';import 'package:qros_mobile_studio/core/remote_session.dart';import 'package:qros_mobile_studio/core/synthetic_jobs.dart';import 'package:qros_mobile_studio/core/universe_ir.dart';import 'package:qros_mobile_studio/core/universe_store.dart';import 'package:qros_mobile_studio/ui/remote_research_screen.dart';String rep(String s,int n)=>List.filled(n,s).join();class S implements SessionGateway{@override Future<RemoteSessionBundle> exchange(String o,String p,String c)async=>RemoteSessionBundle(origin:o,clientId:c,accessToken:rep('A',43),refreshToken:rep('R',43),accessExp:9999999999,refreshExp:9999999999);@override Future<RemoteSessionBundle> refresh(RemoteSessionBundle c)async=>c;@override Future<void> revoke(RemoteSessionBundle c)async{}}class J implements SyntheticJobGateway{@override Future<SyntheticJobSnapshot> create(String o,String a,UniverseSessionDraft d,String i)async=>SyntheticJobSnapshot(id:'job_01234567890123456789',state:'RUNNING',cursor:0,totalUnits:d.blueprint.rawBirths,searchSpaceSha256:d.searchSpaceSha256,toyEnumerationSha256:d.toyEnumerationSha256,resultSha256:null);@override Future<SyntheticJobSnapshot> get(String o,String a,String id)async=>throw UnimplementedError();}void main(){testWidgets('G12 pairing screen stays non scientific',(t)async{final s=RemoteSessionStore(vault:MemoryLocalVault(),gateway:S(),clock:()=>DateTime.utc(2026,10,2));await t.pumpWidget(MaterialApp(home:RemoteResearchScreen(session:s,universeStore:UniverseSessionStore(),jobs:J())));await t.enterText(find.byKey(const Key('g12-origin')),'https://g12.test');await t.enterText(find.byKey(const Key('g12-client')),'client_A');await t.enterText(find.byKey(const Key('g12-pairing')),rep('P',43));await t.tap(find.byKey(const Key('g12-pair')));await t.pumpAndSettle();expect(find.textContaining('Sesión TEST_ONLY vinculada'),findsOneWidget);expect(find.text('APPROVED_FINAL'),findsNothing);});}